package main

import "fmt"

func main() {
	nota := 7

	if nota >= 9 {
		fmt.Println("Sobresaliente")
	} else if nota >= 7 {
		fmt.Println("Notable")
	} else if nota >= 5 {
		fmt.Println("Aprobado")
	} else {
		fmt.Println("Suspenso")
	}
	// Sale: Notable
}

package main

import "fmt"

func main() {
	edad := 20
	tieneEntrada := true
	lleno := false

	if edad >= 18 && tieneEntrada {
		fmt.Println("Puedes entrar")
	}

	if !lleno {
		fmt.Println("Queda sitio")
	}
}

package main

import "fmt"

func main() {
	dia := "sábado"

	switch dia {
	case "sábado", "domingo":
		fmt.Println("Fin de semana")
	case "viernes":
		fmt.Println("Casi finde")
	default:
		fmt.Println("Día laborable")
	}
	// Sale: Fin de semana
}

